// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(bytes calldata _data) public {
        Helper helper = new Helper();
        vm.assume(_data.length > 0);
        uint256 balBefore = address(c).balance;
        vm.deal(address(c), 1);
        balBefore = address(c).balance;
        c.forward(address(helper), _data);
        uint256 balAfter = address(c).balance;
        assertTrue(balAfter == balBefore);
    }
}

contract Helper {
    fallback() external payable {
        selfdestruct(payable(address(0)));
    }
}
